mapper.select:

		select p.*, m.nickname,
        (
            SELECT COUNT(*)
            FROM post_like pl
            WHERE pl.post_id = p.post_id
        ) AS like_count
		from study_post p 
		join member m 
		on p.member_id = m.member_id 
		where p.study_id= #{studyId} 
		and p.post_type = #{postType} 
		order by p.created_at desc 

			limit #{limit}

select exists(
	select 1
	from post_like
	where post_id = #{postId}
		and member_id = #{memberId}
)

mapper.delete:
delete from post_like
where post_id = #{postId}
	and member_id = #{memberId}
